import{_ as i,o,c as l,a2 as r}from"./chunks/framework.DPTp4bo7.js";const f=JSON.parse('{"title":"产线设计理论研究","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://kokobird28144.github.io/endfield-skydoc/zh/research-into-production-line-design-theory"}],["link",{"rel":"alternate","hreflang":"en","href":"https://kokobird28144.github.io/endfield-skydoc/research-into-production-line-design-theory"}],["link",{"rel":"alternate","hreflang":"zh-CN","href":"https://kokobird28144.github.io/endfield-skydoc/zh/research-into-production-line-design-theory"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://kokobird28144.github.io/endfield-skydoc/research-into-production-line-design-theory"}]]},"headers":[],"relativePath":"zh/research-into-production-line-design-theory.md","filePath":"zh/page-AkKxBGcG2kq2AD8Tl6Nicw.md"}'),a={name:"zh/research-into-production-line-design-theory.md"};function n(t,e,d,c,p,s){return o(),l("div",null,[...e[0]||(e[0]=[r('<div class="logistics-content"><span class="logistics-source-anchor" id="产线设计理论研究" aria-hidden="true"></span><span class="logistics-source-anchor" id="production-line-design-theory" aria-hidden="true"></span><h1 id="产线设计理论研究" tabindex="-1">产线设计理论研究 <a class="header-anchor" href="#产线设计理论研究" aria-label="Permalink to &quot;产线设计理论研究&quot;">​</a></h1><blockquote><p>源页面 ID：<code>AkKxBGcG2kq2AD8Tl6Nicw</code> ｜ <a href="https://docs.qq.com/aio/DTmluZ1diWlpQZldw?p=AkKxBGcG2kq2AD8Tl6Nicw" target="_blank" rel="noreferrer">在腾讯文档中打开</a></p></blockquote><p>产线设计流程应当包括：</p><ol><li>产线基本概念设计。如尽可能简化的全部生产重息壤，不产铜产物、再如尽可能最大化调度券产出、在满足兑换调度券下的最大的某种装备元件产量。</li></ol><p><a href="/endfield-skydoc/zh/reference-for-common-production-line-concepts">常见的产线概念参考</a></p><ol><li>产线量化计算。例如使用量化计算器计算最大调度券产量的产线分配；计算最大重息壤产量需要多少设备。</li></ol><p><a href="/endfield-skydoc/zh/modified-quantitative-calculator">魔改量化计算器</a></p><ol><li>产线优先级设计。可选，对于复杂需求，如果需要使用自适应方式实现，需要先设计优先级分配方式。</li></ol><p><a href="/endfield-skydoc/zh/conventional-priority-architectures">常规优先级架构（不是结构）</a></p><ol><li>产线划分。决定哪些过程产物、中间产物可以入库，进而将复杂的具体流程简化为各部分产线。</li></ol><p><a href="/endfield-skydoc/zh/research-on-criteria-for-identifying-raw-materials">原料判定依据研究</a></p><ol><li>产线设备合并。根据基本概念可选，决定混产情况与所需控制结构设计。</li></ol><p><a href="/endfield-skydoc/zh/research-on-theory-and-practice-of-complex-serial-parallel-mixed">复杂串并行混产理论与实践研究</a></p><ol><li>产线位置分配。将具体各部分产线大致搭好确定大小，然后根据资源量、占地将产线分给不同基地。例如 液气提纯灼铜 适合在应龙关造而不适合在武陵城造，因为武陵城没有酸液。如果有必要，可以在同时考虑跨地区暗管。</li></ol><p><a href="/endfield-skydoc/zh/modified-quantitative-calculator">魔改量化计算器</a></p><ol><li>最终产线初步搭建\\产线节点搭建。将上一步确定的部分产线搭建并压缩。</li></ol><p><a href="/endfield-skydoc/zh/related-links">友情链接</a>，<a href="/endfield-skydoc/zh/developing-tools-and-algorithms-for-production-line-compression">产线压缩相关工具和算法的开发</a></p><ol><li><p>最终产线调整。在有不合适的设计的地方进行调整重新分配，将具体压缩的产线组合起来确认是否能进一步压缩。然后连接基地内外的暗管。</p></li><li><p>最终产线总装。可选，如果有跨地区暗管，可以在这一步再安装连接。</p></li><li><p>产线评价。可选，判定该产线是否符合最初的目的，优化程度如何，相比其他同目标或者最大化目标的产线有什么区别等。</p></li></ol><p>相关工具设计分布</p><p>[1]</p><p>[2]量化计算器</p><p>[3]flow-viewer产线图，(自配平原理)</p><p>[4]需求产线划分工具与原料确认工具，或者可能也需要放在量化计算器中</p><p>[5]可能也要在量化计算器</p><p>[6]需求产线位置分配计算规则及工具</p><p>[7]需求<a href="/endfield-skydoc/zh/developing-tools-and-algorithms-for-production-line-compression">产线压缩相关工具和算法的开发</a></p><p>[8]</p><p>[9]</p></div>',1)])])}const k=i(a,[["render",n]]);export{f as __pageData,k as default};
